// src/linear_model/mod.rs
impl LinearRegression { pub fn save_safetensors<P: AsRef<Path>>(&self, path: P) -> Result<(), String> { use crate::serialization::safetensors; use std::collections::BTreeMap; let coefficients = self.coefficients .as_ref() .ok_or("Cannot save unfitted model. Call fit() first.")?; let mut tensors = BTreeMap::new(); // Coefficients tensor let coef_data: Vec<f32> = (0..coefficients.len()) .map(|i| coefficients[i]) .collect(); tensors.insert("coefficients".to_string(), (coef_data, vec![coefficients.len()])); // Intercept tensor tensors.insert("intercept".to_string(), (vec![self.intercept], vec![1])); safetensors::save_safetensors(path, tensors)?; Ok(()) } pub fn load_safetensors<P: AsRef<Path>>(path: P) -> Result<Self, String> { use crate::serialization::safetensors; let (metadata, raw_data) = safetensors::load_safetensors(path)?; // Extract coefficients let coef_meta = metadata.get("coefficients") .ok_or("Missing 'coefficients' tensor")?; let coef_data = safetensors::extract_tensor(&raw_data, coef_meta)?; // Extract intercept let intercept_meta = metadata.get("intercept") .ok_or("Missing 'intercept' tensor")?; let intercept_data = safetensors::extract_tensor(&raw_data, intercept_meta)?; if intercept_data.len() != 1 { return Err(format!("Invalid intercept: expected 1 value, got {}", intercept_data.len())); } Ok(Self { coefficients: Some(Vector::from_vec(coef_data)), intercept: intercept_data[0], fit_intercept: true, }) }
}

