use aprender::code::{ pooling, AstNode, AstNodeType, Code2VecEncoder, CodeEdgeType, CodeGraph, CodeGraphEdge, CodeGraphNode, CodeMPNN, PathExtractor,
}; fn main() { // 1. Build AST for: fn add(x, y) -> x + y let mut func = AstNode::new(AstNodeType::Function, "add"); func.add_child(AstNode::new(AstNodeType::Parameter, "x")); func.add_child(AstNode::new(AstNodeType::Parameter, "y")); let mut body = AstNode::new(AstNodeType::Block, "body"); let mut op = AstNode::new(AstNodeType::BinaryOp, "+"); op.add_child(AstNode::new(AstNodeType::Variable, "x")); op.add_child(AstNode::new(AstNodeType::Variable, "y")); let mut ret = AstNode::new(AstNodeType::Return, "return"); ret.add_child(op); body.add_child(ret); func.add_child(body); // 2. Extract paths and generate embedding let extractor = PathExtractor::new(8); let paths = extractor.extract(&func); println!("Extracted {} paths", paths.len()); let encoder = Code2VecEncoder::new(64); let embedding = encoder.aggregate_paths(&paths); println!("Function embedding: {} dimensions", embedding.dim()); // 3. Build code graph for MPNN let mut graph = CodeGraph::new(); graph.add_node(CodeGraphNode::new(0, vec![1.0, 0.0], "param_x")); graph.add_node(CodeGraphNode::new(1, vec![0.0, 1.0], "param_y")); graph.add_node(CodeGraphNode::new(2, vec![0.5, 0.5], "add_op")); graph.add_edge(CodeGraphEdge::new(0, 2, CodeEdgeType::DataFlow)); graph.add_edge(CodeGraphEdge::new(1, 2, CodeEdgeType::DataFlow)); // 4. Run MPNN let mpnn = CodeMPNN::new(&[2, 8, 4]); let node_embs = mpnn.forward(&graph); let graph_emb = pooling::mean_pool(&node_embs); println!("Graph embedding: {:?}", &graph_emb[..4]);
}

