1980.body:
use aprender::classification::{KNearestNeighbors, DistanceMetric};
use aprender::primitives::Matrix; // 1. Load data
let (x_train, y_train, x_test, y_test) = load_iris_data()?; // 2. Basic kNN
let mut knn = KNearestNeighbors::new(3);
knn.fit(&x_train, &y_train)?;
let predictions = knn.predict(&x_test)?;
println!("Accuracy: {:.1}%", compute_accuracy(&predictions, &y_test) * 100.0); // 3. Hyperparameter tuning
for k in [1, 3, 5, 7, 9] { let mut knn = KNearestNeighbors::new(k); knn.fit(&x_train, &y_train)?; let acc = compute_accuracy(&knn.predict(&x_test)?, &y_test); println!("k={}: {:.1}%", k, acc * 100.0);
} // 4. Best model with weighted voting
let mut knn_best = KNearestNeighbors::new(5) .with_weights(true);
knn_best.fit(&x_train, &y_train)?; // 5. Probabilistic predictions
let probabilities = knn_best.predict_proba(&x_test)?;
for (i, &pred) in knn_best.predict(&x_test)?.iter().enumerate() { println!("Sample {}: class={}, confidence={:.1}%", i, pred, probabilities[i][pred] * 100.0);
}

