fn simulate_lotka_volterra( params: &LotkaVolterraParams, x0: f64, // Initial prey y0: f64, // Initial predator dt: f64, // Time step steps: usize, // Simulation length
) -> Vec<(f64, f64)> { let mut trajectory = Vec::with_capacity(steps); let mut x = x0; let mut y = y0; for _ in 0..steps { trajectory.push((x, y)); // Lotka-Volterra equations (Euler method) let dx = params.alpha * x - params.beta * x * y; let dy = params.delta * x * y - params.gamma * y; x += dx * dt; y += dy * dt; x = x.max(0.0); // Prevent negative populations y = y.max(0.0); } trajectory
}

