Join step : Combine two (k-1)-itemsets that differ by exactly one item fn generate_candidates(&self, prev_itemsets: &[(HashSet<usize>, f64)]) -> Vec<HashSet<usize>> { let mut candidates = Vec::new(); for i in 0..prev_itemsets.len() { for j in (i + 1)..prev_itemsets.len() { let set1 = &prev_itemsets[i].0; let set2 = &prev_itemsets[j].0; let union: HashSet<usize> = set1.union(set2).copied().collect(); if union.len() == set1.len() + 1 { // Valid k-itemset candidate if !self.has_infrequent_subset(&union, prev_itemsets) { candidates.push(union); } } } } candidates
} Prune step : Remove candidates with infrequent (k-1)-subsets fn has_infrequent_subset(&self, itemset: &HashSet<usize>, prev_itemsets: &[(HashSet<usize>, f64)]) -> bool { for &item in itemset { let mut subset = itemset.clone(); subset.remove(&item); let is_frequent = prev_itemsets.iter().any(|(freq_set, _)| freq_set == &subset); if !is_frequent { return true; // Prune this candidate } } false
}

