Complete workflow from raw text to predictions. use aprender::classification::GaussianNB;
use aprender::text::stem::{PorterStemmer, Stemmer};
use aprender::text::stopwords::StopWordsFilter;
use aprender::text::tokenize::WhitespaceTokenizer;
use aprender::text::vectorize::TfidfVectorizer;
use aprender::text::Tokenizer; fn main() { let raw_docs = vec![ "The machine learning algorithms are improving rapidly", "The team scored three goals in the championship match", ]; let labels = vec![0, 1]; // 0 = tech, 1 = sports // Step 1: Tokenization let tokenizer = WhitespaceTokenizer::new(); let tokenized: Vec<Vec<String>> = raw_docs .iter() .map(|doc| tokenizer.tokenize(doc).unwrap()) .collect(); // Step 2: Lowercase + Stop words filtering let filter = StopWordsFilter::english(); let filtered: Vec<Vec<String>> = tokenized .iter() .map(|tokens| { let lower: Vec<String> = tokens.iter().map(|t| t.to_lowercase()).collect(); filter.filter(&lower).unwrap() }) .collect(); // Step 3: Stemming let stemmer = PorterStemmer::new(); let stemmed: Vec<Vec<String>> = filtered .iter() .map(|tokens| stemmer.stem_tokens(tokens).unwrap()) .collect(); println!("After preprocessing: {:?}", stemmed[0]); // ["machin", "learn", "algorithm", "improv", "rapid"] // Step 4: Rejoin and vectorize let processed: Vec<String> = stemmed .iter() .map(|tokens| tokens.join(" ")) .collect(); let mut vectorizer = TfidfVectorizer::new() .with_tokenizer(Box::new(WhitespaceTokenizer::new())); let X = vectorizer.fit_transform(&processed).unwrap(); // Step 5: Classification let X_f32 = convert_to_f32(&X); let mut classifier = GaussianNB::new(); classifier.fit(&X_f32, &labels).unwrap(); let predictions = classifier.predict(&X_f32).unwrap(); println!("Predictions: {:?}", predictions); // [0, 1] = [tech, sports]
} Output: After preprocessing: ["machin", "learn", "algorithm", "improv", "rapid"]
Predictions: [0, 1] Pipeline Analysis: Stage Input Output Effect Tokenization "The machine learning..." ["The", "machine", ...] Split into words Lowercase + Stop words 11 tokens 8 tokens Remove "the", "are", "in" Stemming ["machine", "learning"] ["machin", "learn"] Normalize to roots TF-IDF Text tokens 31-dimensional vectors Numerical features Classification Feature vectors Class labels Predictions Key Benefits: Vocabulary reduction : 27% fewer tokens after stop words Normalization : "improving" → "improv", "algorithms" → "algorithm" Generalization : Stemming helps match "learn", "learning", "learned" Discriminative features : TF-IDF highlights important words

