use aprender::primitives::Vector;
use aprender::text::entities::EntityExtractor;
use aprender::text::similarity::{ cosine_similarity, edit_distance, jaccard_similarity, top_k_similar,
};
use aprender::text::summarize::{SummarizationMethod, TextSummarizer};
use aprender::text::tokenize::WhitespaceTokenizer;
use aprender::text::vectorize::TfidfVectorizer; fn main() { // --- 1. Document Similarity --- let documents = vec![ "Machine learning is a subset of artificial intelligence", "Deep learning uses neural networks for pattern recognition", "Machine learning algorithms learn from data", "Natural language processing analyzes human language", ]; // Compute TF-IDF vectors let tokenizer = Box::new(WhitespaceTokenizer::new()); let mut vectorizer = TfidfVectorizer::new().with_tokenizer(tokenizer); let tfidf_matrix = vectorizer .fit_transform(&documents) .expect("TF-IDF transformation should succeed"); // Extract document vectors let doc_vectors: Vec<Vector<f64>> = (0..documents.len()) .map(|i| { let row: Vec<f64> = (0..tfidf_matrix.n_cols()) .map(|j| tfidf_matrix.get(i, j)) .collect(); Vector::from_slice(&row) }) .collect(); // Compute cosine similarity let similarity = cosine_similarity(&doc_vectors[0], &doc_vectors[2]) .expect("Cosine similarity should succeed"); println!("Cosine similarity: {:.3}", similarity); // Output: Cosine similarity: 0.173 // Find top-k most similar documents let query = doc_vectors[0].clone(); let candidates = doc_vectors[1..].to_vec(); let top_similar = top_k_similar(&query, &candidates, 2) .expect("Top-k should succeed"); println!("\\nTop 2 most similar:"); for (idx, score) in &top_similar { println!(" [{}] {:.3}", idx, score); } // Output: // [2] 0.173 // [1] 0.056 // Jaccard similarity (token overlap) let tokenized: Vec<Vec<&str>> = documents .iter() .map(|d| d.split_whitespace().collect()) .collect(); let jaccard = jaccard_similarity(&tokenized[0], &tokenized[2]) .expect("Jaccard should succeed"); println!("\\nJaccard similarity: {:.3}", jaccard); // Output: Jaccard similarity: 0.167 // Edit distance (string matching) let distance = edit_distance("machine learning", "deep learning") .expect("Edit distance should succeed"); println!("\\nEdit distance: {} edits", distance); // Output: Edit distance: 7 edits // --- 2. Entity Extraction --- let text = "Contact @john_doe at john@example.com or visit https://example.com. \ Call 555-123-4567 for support. #MachineLearning #AI"; let extractor = EntityExtractor::new(); let entities = extractor.extract(text) .expect("Extraction should succeed"); println!("\\n--- Extracted Entities ---"); println!("Emails: {:?}", entities.emails); // Output: Emails: ["john@example.com"] println!("URLs: {:?}", entities.urls); // Output: URLs: ["https://example.com"] println!("Phone: {:?}", entities.phone_numbers); // Output: Phone: ["555-123-4567"] println!("Mentions: {:?}", entities.mentions); // Output: Mentions: ["@john_doe"] println!("Hashtags: {:?}", entities.hashtags); // Output: Hashtags: ["#MachineLearning", "#AI"] println!("Total entities: {}", entities.total_count()); // Output: Total entities: 5+ // --- 3. Text Summarization --- let long_text = "Machine learning is a subset of artificial intelligence that \ focuses on the development of algorithms and statistical models. \ These algorithms enable computer systems to improve their \ performance on tasks through experience. Deep learning is a \ specialized branch of machine learning that uses neural networks \ with multiple layers. Natural language processing is another \ important area of AI that deals with the interaction between \ computers and human language."; // TF-IDF summarization let tfidf_summarizer = TextSummarizer::new( SummarizationMethod::TfIdf, 2 // Top 2 sentences ); let summary = tfidf_summarizer.summarize(long_text) .expect("Summarization should succeed"); println!("\\n--- TF-IDF Summary (2 sentences) ---"); for sentence in &summary { println!(" - {}", sentence); } // TextRank summarization (graph-based) let textrank_summarizer = TextSummarizer::new( SummarizationMethod::TextRank, 2 ) .with_damping_factor(0.85) .with_max_iterations(100); let textrank_summary = textrank_summarizer.summarize(long_text) .expect("TextRank should succeed"); println!("\\n--- TextRank Summary (2 sentences) ---"); for sentence in &textrank_summary { println!(" - {}", sentence); } // Hybrid summarization (best of both) let hybrid_summarizer = TextSummarizer::new( SummarizationMethod::Hybrid, 2 ); let hybrid_summary = hybrid_summarizer.summarize(long_text) .expect("Hybrid should succeed"); println!("\\n--- Hybrid Summary (2 sentences) ---"); for sentence in &hybrid_summary { println!(" - {}", sentence); }
}

