Implemented HNSW with probabilistic skip-list structure: use crate::primitives::Vector;
use rand::Rng;
use std::collections::HashMap; #[derive(Debug)]
pub struct HNSWIndex { m: usize, // Max connections per node max_m0: usize, // Max connections for layer 0 (2*M) ef_construction: usize, // Construction parameter ml: f64, // Level multiplier (1/ln(2)) nodes: Vec<Node>, item_to_node: HashMap<String, usize>, entry_point: Option<usize>, rng: rand::rngs::ThreadRng,
} #[derive(Debug, Clone)]
struct Node { item_id: String, vector: Vector<f64>, connections: Vec<Vec<usize>>, // Connections per layer
} impl HNSWIndex { pub fn new(m: usize, ef_construction: usize, _level_probability: f64) -> Self { Self { m, max_m0: 2 * m, ef_construction, ml: 1.0 / (2.0_f64).ln(), nodes: Vec::new(), item_to_node: HashMap::new(), entry_point: None, rng: rand::thread_rng(), } } pub fn add(&mut self, item_id: impl Into<String>, vector: Vector<f64>) { let item_id = item_id.into(); let node_id = self.nodes.len(); // Determine layer for new node let layer = self.random_layer(); // Create node with connections for each layer let mut connections = vec![Vec::new(); layer + 1]; let node = Node { item_id: item_id.clone(), vector, connections, }; self.nodes.push(node); self.item_to_node.insert(item_id, node_id); if self.entry_point.is_none() { self.entry_point = Some(node_id); return; } // Insert into graph layers self.insert_node(node_id, layer); } pub fn search(&self, query: &Vector<f64>, k: usize) -> Vec<(String, f64)> { if self.nodes.is_empty() { return Vec::new(); } let entry = self.entry_point.unwrap(); let top_layer = self.nodes[entry].connections.len() - 1; // Search from top layer down let mut current = entry; for layer in (1..=top_layer).rev() { current = self.search_layer(query, current, 1, layer)[0].0; } // Search at layer 0 let mut candidates = self.search_layer(query, current, k, 0); candidates.truncate(k); candidates .into_iter() .map(|(node_id, dist)| (self.nodes[node_id].item_id.clone(), dist)) .collect() } fn distance(&self, a: &Vector<f64>, b: &Vector<f64>) -> f64 { // Cosine distance: 1.0 - cos_similarity let dot: f64 = a.as_slice() .iter() .zip(b.as_slice().iter()) .map(|(x, y)| x * y) .sum(); let norm_a: f64 = a.as_slice() .iter() .map(|x| x * x) .sum::<f64>() .sqrt(); let norm_b: f64 = b.as_slice() .iter() .map(|x| x * x) .sum::<f64>() .sqrt(); 1.0 - (dot / (norm_a * norm_b)).min(1.0).max(-1.0) } fn random_layer(&mut self) -> usize { let uniform: f64 = self.rng.gen(); (-uniform.ln() * self.ml).floor() as usize }
} Verification: $ cargo test hnsw
