Implemented content-based recommender integrating HNSW + IDF + TF-IDF: use crate::error::AprenderError;
use crate::index::hnsw::HNSWIndex;
use crate::primitives::Vector;
use crate::text::incremental_idf::IncrementalIDF;
use crate::text::tokenize::WhitespaceTokenizer;
use crate::text::Tokenizer;
use std::collections::HashMap; #[derive(Debug)]
pub struct ContentRecommender { hnsw: HNSWIndex, idf: IncrementalIDF, item_content: HashMap<String, String>, tokenizer: WhitespaceTokenizer,
} impl ContentRecommender { pub fn new(m: usize, ef_construction: usize, decay_factor: f64) -> Self { Self { hnsw: HNSWIndex::new(m, ef_construction, 0.0), idf: IncrementalIDF::new(decay_factor), item_content: HashMap::new(), tokenizer: WhitespaceTokenizer::new(), } } pub fn add_item(&mut self, item_id: impl Into<String>, content: impl Into<String>) { let item_id = item_id.into(); let content = content.into(); // Tokenize let tokens = self .tokenizer .tokenize(&content) .unwrap_or_else(|_| Vec::new()); // Get unique terms for IDF update let unique_terms: Vec<String> = tokens .iter() .map(|s| s.to_lowercase()) .collect::<std::collections::HashSet<_>>() .into_iter() .collect(); // Update IDF with unique terms let term_refs: Vec<&str> = unique_terms.iter().map(String::as_str).collect(); self.idf.update(&term_refs); // Compute TF-IDF vector let tfidf_vec = self.compute_tfidf(&tokens); // Add to HNSW index self.hnsw.add(item_id.clone(), tfidf_vec); // Store content self.item_content.insert(item_id, content); } pub fn recommend( &self, item_id: &str, k: usize, ) -> Result<Vec<(String, f64)>, AprenderError> { // Get item content let content = self .item_content .get(item_id) .ok_or_else(|| AprenderError::Other(format!("Item not found: {}", item_id)))?; // Compute TF-IDF for query let tokens = self.tokenizer.tokenize(content)?; let query_vec = self.compute_tfidf(&tokens); // Search HNSW (returns k+1 to exclude query item) let results = self.hnsw.search(&query_vec, k + 1); // Filter out query item and convert distance to similarity let recommendations: Vec<(String, f64)> = results .into_iter() .filter(|(id, _)| id != item_id) .take(k) .map(|(id, dist)| { // Convert cosine distance to cosine similarity // distance = 1 - similarity, so similarity = 1 - distance let similarity = 1.0 - dist; (id, similarity) }) .collect(); Ok(recommendations) } pub fn len(&self) -> usize { self.item_content.len() } pub fn is_empty(&self) -> bool { self.item_content.is_empty() } fn compute_tfidf(&self, tokens: &[String]) -> Vector<f64> { // Compute term frequencies let mut tf: HashMap<String, f64> = HashMap::new(); for token in tokens { let term = token.to_lowercase(); *tf.entry(term).or_insert(0.0) += 1.0; } // Normalize TF by max frequency let max_tf = tf.values().copied().fold(0.0, f64::max); if max_tf > 0.0 { for value in tf.values_mut() { *value /= max_tf; } } // Get all vocabulary terms let vocab: Vec<String> = self.idf.terms().keys().cloned().collect(); // Compute TF-IDF vector let tfidf: Vec<f64> = vocab .iter() .map(|term| { let tf_val = tf.get(term).copied().unwrap_or(0.0); let idf_val = self.idf.idf(term); tf_val * idf_val }) .collect(); Vector::from_vec(tfidf) }
} Verification: $ cargo test recommend
