use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion}; fn generate_movie_descriptions(n: usize) -> Vec<(String, String)> { let genres = [ "action", "comedy", "drama", "thriller", "horror", "romance", "scifi", "fantasy", "mystery", "adventure", ]; let adjectives = [ "epic", "thrilling", "emotional", "intense", "hilarious", "dark", "heartwarming", "suspenseful", "mysterious", "explosive", ]; let nouns = [ "story", "journey", "adventure", "tale", "saga", "quest", "mission", "odyssey", "expedition", "voyage", ]; (0..n) .map(|i| { let genre = genres[i % genres.len()]; let adj = adjectives[(i / 10) % adjectives.len()]; let noun = nouns[(i / 100) % nouns.len()]; let id = format!("movie_{}", i); let desc = format!("{} {} {} about heroes and villains", adj, genre, noun); (id, desc) }) .collect()
} fn bench_recommend_latency_target(c: &mut Criterion) { // Verify <100ms latency for 10,000 items let mut rec = ContentRecommender::new(16, 200, 0.95); let items = generate_movie_descriptions(10_000); for (id, desc) in items { rec.add_item(id, desc); } c.bench_function("recommend_10k_latency", |b| { b.iter(|| { rec.recommend(black_box("movie_5000"), black_box(10)) .expect("should succeed") }); });
