use std::collections::HashMap; /// N-gram frequency table
/// Maps context (previous n-1 tokens) → next token → count
#[derive(Default)]
struct NgramTable { /// context → (next_token → frequency) table: HashMap<String, HashMap<String, u32>>,
} impl NgramTable { fn new() -> Self { Self::default() } /// Record an observation: given context, next token appeared fn observe(&mut self, context: &str, next_token: &str) { self.table .entry(context.to_string()) .or_default() .entry(next_token.to_string()) .and_modify(|c| *c += 1) .or_insert(1); } /// Get probability distribution for context fn predict(&self, context: &str) -> Vec<(String, f32)> { let Some(counts) = self.table.get(context) else { return vec![]; }; let total: u32 = counts.values().sum(); let mut probs: Vec<_> = counts .iter() .map(|(token, count)| { (token.clone(), *count as f32 / total as f32) }) .collect(); // Sort by probability descending probs.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap()); probs }
} // Test: Empty table returns empty predictions
