Learn error→fix patterns from training data: use std::collections::HashMap; pub struct FixPattern { pub error_pattern: String, pub fix_template: String, pub category: ErrorCategory, pub frequency: usize, pub success_rate: f32,
} pub struct NgramFixPredictor { patterns: HashMap<ErrorCategory, Vec<FixPattern>>, min_similarity: f32,
} impl NgramFixPredictor { pub fn new() -> Self { Self { patterns: HashMap::new(), min_similarity: 0.1, } } /// Learn a new error-fix pattern pub fn learn_pattern( &mut self, error_message: &str, fix_template: &str, category: ErrorCategory, ) { let normalized = self.normalize(error_message); let patterns = self.patterns.entry(category).or_default(); if let Some(existing) = patterns.iter_mut() .find(|p| p.error_pattern == normalized) { existing.frequency += 1; } else { patterns.push(FixPattern { error_pattern: normalized, fix_template: fix_template.to_string(), category, frequency: 1, success_rate: 0.0, }); } } /// Predict fixes for an error pub fn predict(&self, error_message: &str, top_k: usize) -> Vec<FixSuggestion> { let normalized = self.normalize(error_message); let mut suggestions = Vec::new(); for (category, patterns) in &self.patterns { for pattern in patterns { let similarity = self.jaccard_similarity(&normalized, &pattern.error_pattern); if similarity >= self.min_similarity { suggestions.push(FixSuggestion { fix: pattern.fix_template.clone(), confidence: similarity * (1.0 + (pattern.frequency as f32).ln()), category: *category, }); } } } suggestions.sort_by(|a, b| b.confidence.partial_cmp(&a.confidence).unwrap()); suggestions.truncate(top_k); suggestions } fn normalize(&self, msg: &str) -> String { msg.to_lowercase() .replace(|c: char| c.is_ascii_digit(), "N") .replace("error:", "") .trim() .to_string() } fn jaccard_similarity(&self, a: &str, b: &str) -> f32 { let tokens_a: Vec<&str> = a.split_whitespace().collect(); let tokens_b: Vec<&str> = b.split_whitespace().collect(); let set_a: std::collections::HashSet<_> = tokens_a.iter().collect(); let set_b: std::collections::HashSet<_> = tokens_b.iter().collect(); let intersection = set_a.intersection(&set_b).count(); let union = set_a.union(&set_b).count(); if union == 0 { 0.0 } else { intersection as f32 / union as f32 } }
} pub struct FixSuggestion { pub fix: String, pub confidence: f32, pub category: ErrorCategory,
}

