use aprender::format::validation::{Gate, PokaYoke, PokaYokeResult}; struct WhisperModel { has_filterbank: bool, filterbank_max: f32, encoder_layers: usize, vocab_size: usize,
} impl PokaYoke for WhisperModel { fn poka_yoke_validate(&self) -> PokaYokeResult { let mut result = PokaYokeResult::new(); // Gate 1: Filterbank must be embedded (20 points) if self.has_filterbank { result.add_gate(Gate::pass("filterbank_present", 20)); } else { result.add_gate(Gate::fail( "filterbank_present", 20, "Fix: Embed Slaney-normalized filterbank via MelFilterbankData::mel_80()" )); } // Gate 2: Filterbank must be Slaney-normalized (30 points) if self.has_filterbank && self.filterbank_max < 0.1 { result.add_gate(Gate::pass("filterbank_normalized", 30)); } else if self.has_filterbank { result.add_gate(Gate::fail( "filterbank_normalized", 30, format!("Fix: Apply 2.0/bandwidth normalization (max={:.4}, expected <0.1)", self.filterbank_max) )); } // Gate 3: Encoder layers (25 points) if self.encoder_layers >= 4 { result.add_gate(Gate::pass("encoder_layers", 25)); } else { result.add_gate(Gate::fail( "encoder_layers", 25, format!("Fix: Model needs ≥4 encoder layers (has {})", self.encoder_layers) )); } // Gate 4: Vocabulary (25 points) if self.vocab_size > 0 { result.add_gate(Gate::pass("vocabulary_size", 25)); } else { result.add_gate(Gate::fail( "vocabulary_size", 25, "Fix: Set vocabulary size > 0 for tokenization" )); } result }
}

