Implement RoutingPolicyTrait for custom routing logic: use apr_cli::federation::traits::{ RoutingPolicyTrait, RouteCandidate, InferenceRequest,
}; struct TenantAffinityPolicy { weight: f64, tenant_preferences: HashMap<String, String>, // tenant_id -> preferred_node
} impl RoutingPolicyTrait for TenantAffinityPolicy { fn score(&self, candidate: &RouteCandidate, request: &InferenceRequest) -> f64 { if let Some(tenant_id) = &request.tenant_id { if let Some(preferred) = self.tenant_preferences.get(tenant_id) { if candidate.target.node_id.0 == *preferred { return 1.0 * self.weight; // Strong boost for preferred node } } } 0.5 * self.weight // Neutral for non-preferred } fn is_eligible(&self, _candidate: &RouteCandidate, _request: &InferenceRequest) -> bool { true // Affinity is a preference, not a hard requirement } fn name(&self) -> &str { "tenant_affinity" }
}

