fn degree_features(edge_index: &[(usize, usize)], num_nodes: usize) -> Tensor { let mut degrees = vec![0.0f32; num_nodes]; for &(src, _) in edge_index { degrees[src] += 1.0; } // Normalize let max_deg = degrees.iter().cloned().fold(1.0, f32::max); for d in &mut degrees { *d /= max_deg; } Tensor::new(&degrees, &[num_nodes, 1])
} /// Random features (for structure-only learning)
fn random_features(num_nodes: usize, dim: usize) -> Tensor { let data: Vec<f32> = (0..num_nodes * dim) .map(|_| rand::random::<f32>()) .collect(); Tensor::new(&data, &[num_nodes, dim])
}

