Critical : Validation runs DURING conversion, not after. If a tensor fails validation, conversion aborts immediately. /// Validation that runs inline during conversion
pub struct InlineValidator { config: ValidationConfig, report: ValidationReport,
} impl InlineValidator { /// Called for each tensor during conversion pub fn validate_tensor(&mut self, name: &str, data: &[f32]) -> Result<(), ValidationError> { let stats = TensorStats::compute(name, data); // Check for NaN/Inf if stats.nan_count > 0 { return Err(ValidationError::NanDetected { name: name.to_string(), count: stats.nan_count }); } // Check LayerNorm weights (mean should be ~1.0) if name.contains("layer_norm") && name.ends_with(".weight") { if stats.mean < 0.5 || stats.mean > 3.0 { return Err(ValidationError::LayerNormMean { name: name.to_string(), mean: stats.mean, expected: (0.5, 3.0), }); } } Ok(()) }
}

