pub struct KMeans { // Required parameter n_clusters: usize, // Optional parameters with defaults max_iter: usize, tol: f32, random_state: Option<u64>, // State (None until fitted) centroids: Option<Matrix<f32>>,
} impl KMeans { /// Creates a new K-Means with required parameters and sensible defaults. #[must_use] // ← CRITICAL: Warn if result is unused pub fn new(n_clusters: usize) -> Self { Self { n_clusters, max_iter: 300, // Default from sklearn tol: 1e-4, // Default from sklearn random_state: None, // Default: non-deterministic centroids: None, // Not fitted yet } } /// Sets the maximum number of iterations. #[must_use] // ← Consuming self, must use return value pub fn with_max_iter(mut self, max_iter: usize) -> Self { self.max_iter = max_iter; self // Return self for chaining } /// Sets the convergence tolerance. #[must_use] pub fn with_tol(mut self, tol: f32) -> Self { self.tol = tol; self } /// Sets the random seed for reproducibility. #[must_use] pub fn with_random_state(mut self, seed: u64) -> Self { self.random_state = Some(seed); self }
} Key elements: new() takes only required parameters with_*() methods set optional parameters Methods consume self and return Self for chaining #[must_use] attribute warns if result is discarded

