/// Saves the model to a binary file using bincode.
///
/// The file can be loaded later using `load()` to restore the model.
///
/// # Arguments
///
/// * `path` - Path where the model will be saved
///
/// # Errors
///
/// Returns an error if:
/// - Serialization fails (internal error)
/// - File writing fails (permissions, disk full, invalid path)
///
/// # Examples
///
/// ```no_run
/// use aprender::prelude::*;
///
/// let mut model = LinearRegression::new();
/// // ... fit the model ...
///
/// model.save("model.bin").unwrap();
/// ```
pub fn save<P: AsRef<Path>>(&self, path: P) -> std::result::Result<(), String> { let bytes = bincode::serialize(self).map_err(|e| format!("Serialization failed: {}", e))?; fs::write(path, bytes).map_err(|e| format!("File write failed: {}", e))?; Ok(())
} Location: src/linear_model/mod.rs:112-121 Guideline: Document all error conditions for functions returning Result Be specific about when each error occurs Group related errors (e.g., "I/O errors", "validation errors")

