/// Primary trait for supervised learning estimators.
///
/// Estimators implement fit/predict/score following sklearn conventions.
/// Models that implement this trait can be used interchangeably in pipelines,
/// cross-validation, and hyperparameter tuning.
///
/// # Required Methods
///
/// - `fit()`: Train the model on labeled data
/// - `predict()`: Make predictions on new data
/// - `score()`: Evaluate model performance
///
/// # Examples
///
/// ```
/// use aprender::prelude::*;
///
/// fn train_and_evaluate<E: Estimator>(mut estimator: E) -> f32 {
/// let x = Matrix::from_vec(4, 1, vec![1.0, 2.0, 3.0, 4.0]).unwrap();
/// let y = Vector::from_slice(&[3.0, 5.0, 7.0, 9.0]);
///
/// estimator.fit(&x, &y).unwrap();
/// estimator.score(&x, &y)
/// }
///
/// // Works with any Estimator
/// let model = LinearRegression::new();
/// let r2 = train_and_evaluate(model);
/// assert!(r2 > 0.99);
/// ```
pub trait Estimator { /// Fits the model to training data. fn fit(&mut self, x: &Matrix<f32>, y: &Vector<f32>) -> Result<()>; /// Predicts target values for input data. fn predict(&self, x: &Matrix<f32>) -> Vector<f32>; /// Computes the score (R² for regression, accuracy for classification). fn score(&self, x: &Matrix<f32>, y: &Vector<f32>) -> f32;
} Location: src/traits.rs:8-44 Elements: Summary : Purpose of the trait Context : When to implement, design philosophy Required Methods : List and explain each method Examples : Generic function using the trait

